:root {
  --bg: #1a1c2c;
  --card: #29366f;
  --accent: #41a6f6;
  --accent-dark: #2f7fc4;
  --text: #f4f4f4;
  --muted: #a0a8c0;
  --success: #38b764;
  --danger: #ef7d57;
  --pixel: 4px;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  padding: 0;
  min-height: 100%;
}

body {
  background-color: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(65, 166, 246, 0.06) 25%, transparent 25%),
    linear-gradient(-45deg, rgba(65, 166, 246, 0.06) 25%, transparent 25%),
    linear-gradient(45deg, transparent 75%, rgba(65, 166, 246, 0.06) 75%),
    linear-gradient(-45deg, transparent 75%, rgba(65, 166, 246, 0.06) 75%);
  background-size: 32px 32px;
  background-position: 0 0, 0 16px, 16px -16px, -16px 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
}

.game-wrapper {
  width: 100%;
  max-width: 480px;
}

.game-card {
  background: var(--card);
  border: var(--pixel) solid var(--accent);
  border-radius: 0;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.45);
  padding: 28px 24px 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.game-header {
  text-align: center;
}

h1 {
  margin: 0 0 8px;
  font-size: 2rem;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
  text-shadow: 2px 2px 0 rgba(0, 0, 0, 0.5);
}

.subtitle {
  margin: 0;
  font-size: 1rem;
  color: var(--muted);
  line-height: 1.4;
}

.guess-form {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.input-label {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text);
}

.input-row {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
}

#guess-input {
  flex: 1 1 120px;
  min-width: 0;
  font-size: 1.125rem;
  padding: 12px 14px;
  border: var(--pixel) solid var(--accent-dark);
  border-radius: 0;
  background: #0f1222;
  color: var(--text);
  font-family: inherit;
  outline: none;
}

#guess-input::placeholder {
  color: var(--muted);
  opacity: 0.7;
}

#guess-input:focus-visible {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px rgba(65, 166, 246, 0.4);
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 700;
  padding: 12px 20px;
  border: var(--pixel) solid transparent;
  border-radius: 0;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  transition: transform 0.05s ease, background-color 0.15s ease, box-shadow 0.15s ease;
  box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.4);
}

.btn:active {
  transform: translate(2px, 2px);
  box-shadow: 2px 2px 0 rgba(0, 0, 0, 0.4);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn-primary {
  background: var(--accent);
  color: #0f1222;
  border-color: var(--accent);
}

.btn-primary:hover {
  background: #6bb8ff;
}

.btn-secondary {
  background: transparent;
  color: var(--accent);
  border-color: var(--accent);
}

.btn-secondary:hover {
  background: rgba(65, 166, 246, 0.15);
}

.btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  transform: none;
  box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.2);
}

.feedback {
  margin: 0;
  min-height: 1.5em;
  font-size: 1.125rem;
  font-weight: 600;
  text-align: center;
  line-height: 1.4;
  padding: 12px;
  border: var(--pixel) dashed var(--muted);
  background: rgba(0, 0, 0, 0.2);
}

.feedback.high {
  color: var(--danger);
  border-color: var(--danger);
}

.feedback.low {
  color: var(--accent);
  border-color: var(--accent);
}

.feedback.correct {
  color: var(--success);
  border-color: var(--success);
  background: rgba(56, 183, 100, 0.12);
}

.feedback.error {
  color: var(--danger);
  border-color: var(--danger);
}

.status-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
}

.guess-count {
  font-size: 1rem;
  color: var(--muted);
}

.guess-count strong {
  color: var(--text);
  font-size: 1.125rem;
}

@media (max-width: 400px) {
  .game-card {
    padding: 20px 16px 18px;
  }
  h1 {
    font-size: 1.6rem;
  }
  .input-row {
    flex-direction: column;
  }
  .btn {
    width: 100%;
  }
}

(function () {
  'use strict';

  const MIN = 1;
  const MAX = 100;

  const form = document.getElementById('guess-form');
  const input = document.getElementById('guess-input');
  const guessBtn = document.getElementById('guess-btn');
  const newGameBtn = document.getElementById('new-game-btn');
  const feedback = document.getElementById('feedback');
  const countEl = document.getElementById('guess-count');

  let target = 0;
  let guesses = 0;
  let gameOver = false;

  function randomTarget() {
    return Math.floor(Math.random() * (MAX - MIN + 1)) + MIN;
  }

  function setFeedback(message, cls) {
    feedback.textContent = message;
    feedback.className = 'feedback' + (cls ? ' ' + cls : '');
  }

  function updateCount() {
    countEl.textContent = String(guesses);
  }

  function startGame() {
    target = randomTarget();
    guesses = 0;
    gameOver = false;
    updateCount();
    setFeedback('Make your first guess!', '');
    input.value = '';
    input.disabled = false;
    guessBtn.disabled = false;
    input.focus();
  }

  function handleGuess(event) {
    event.preventDefault();
    if (gameOver) return;

    const raw = input.value.trim();

    if (raw === '') {
      setFeedback('Please enter a number between 1 and 100.', 'error');
      input.focus();
      return;
    }

    const value = Number(raw);

    if (!Number.isFinite(value) || !Number.isInteger(value)) {
      setFeedback('Whole numbers only, please. Try again.', 'error');
      input.focus();
      return;
    }

    if (value < MIN || value > MAX) {
      setFeedback('Out of range! Pick a number from 1 to 100.', 'error');
      input.focus();
      return;
    }

    guesses += 1;
    updateCount();

    if (value === target) {
      gameOver = true;
      setFeedback(
        'Correct! You got it in ' + guesses + ' ' + (guesses === 1 ? 'guess' : 'guesses') + '.',
        'correct'
      );
      input.disabled = true;
      guessBtn.disabled = true;
      newGameBtn.focus();
    } else if (value > target) {
      setFeedback('Too high! Try a lower number.', 'high');
      input.select();
    } else {
      setFeedback('Too low! Try a higher number.', 'low');
      input.select();
    }
  }

  form.addEventListener('submit', handleGuess);
  newGameBtn.addEventListener('click', startGame);

  startGame();
})();
